#!/usr/bin/env python3
"""Generate translations from source files and track whether they are stale.
Edit only the source files; translations are produced by this script.

    python3 scripts/translate.py            # regenerate stale translations (needs the claude CLI)
    python3 scripts/translate.py --check    # report stale translations only, no model call
    python3 scripts/translate.py --force    # regenerate everything

The first line of every translation records its source file and a hash of the source content:
    <!-- i18n: source=README.md sha=0123456789ab | generated by scripts/translate.py, edit the source instead -->
If the source changes and the translation isn't regenerated, the hash no longer matches;
--check and validate.py report it as stale (a warning only; CI does not fail).
"""
import argparse
import hashlib
import re
import subprocess
import sys
import tempfile
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent

# (source, translation, target language). To translate another file, add a row here.
PAIRS = [
    ("README.md", "README_CN.md", "Simplified Chinese"),
    ("prompts/quick-prompt.md", "prompts/quick-prompt-zh.md", "Simplified Chinese"),
]

# links between source files are rewritten to the translated counterparts
LINK_MAP = {src: dst for src, dst, _ in PAIRS}

REASON = {"stale": "the source changed", "missing": "the translation does not exist", "untracked": "the translation has no source header"}

HEADER_RE = re.compile(r"^<!-- i18n: source=(\S+) sha=([0-9a-f]+) .*?-->\n")

SYSTEM_PROMPT = """You are a translator for a GitHub repository's documentation. Translate the Markdown document the user sends into {lang}.

Rules:
- Output only the translated document. No preamble, no explanation, no code fence around the whole document.
- Keep the Markdown structure exactly: headings, tables, lists, HTML tags, <details> blocks, code blocks.
- Do not translate code blocks, commands, file paths, URLs, or identifiers in backticks.
- Rewrite these relative links to their {lang} counterparts: {links}.
- In-page anchor links (href="#..." or (#...)) must point to the translated headings: use the GitHub anchor of the translated heading text (lowercase, spaces to hyphens, punctuation dropped; Chinese characters stay as-is).
- A language switcher (e.g. "English · [中文](README_CN.md)" or the same with <a href>) must link back to the source: the current language becomes plain text and the source language becomes a link to the source file (e.g. "[English](README.md) · 中文"), keeping the original syntax (Markdown or HTML).
- Keep the tone: direct, concise, no hedging. Do not add or drop content."""


def sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]


def status(src: str, dst: str):
    """Return (state, recorded_sha, current_sha). state: ok | stale | missing | untracked."""
    current = sha((REPO / src).read_text(encoding="utf-8"))
    path = REPO / dst
    if not path.exists():
        return "missing", None, current
    m = HEADER_RE.match(path.read_text(encoding="utf-8"))
    if not m:
        return "untracked", None, current
    return ("ok" if m.group(2) == current else "stale"), m.group(2), current


def translate(src: str, dst: str, lang: str, model: str) -> None:
    source = (REPO / src).read_text(encoding="utf-8")
    links = ", ".join(f"{a} -> {b}" for a, b in LINK_MAP.items())
    with tempfile.TemporaryDirectory() as tmp:  # run outside the repo so project context isn't loaded
        out = subprocess.run(
            ["claude", "-p", "--model", model, "--tools", "", "--no-session-persistence",
             "--system-prompt", SYSTEM_PROMPT.format(lang=lang, links=links)],
            input=source, capture_output=True, text=True, cwd=tmp, check=True,
        ).stdout.strip()
    # deterministic fix-up: a link whose text is the source path should show the translated path too
    for a, b in LINK_MAP.items():
        out = out.replace(f"[`{a}`]({b})", f"[`{b}`]({b})")
    header = f"<!-- i18n: source={src} sha={sha(source)} | generated by scripts/translate.py, edit the source instead -->\n"
    (REPO / dst).write_text(header + out + "\n", encoding="utf-8")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true", help="only report stale translations")
    ap.add_argument("--force", action="store_true", help="regenerate all translations")
    ap.add_argument("--model", default="sonnet")
    args = ap.parse_args()

    todo = []
    for src, dst, lang in PAIRS:
        state, _, _ = status(src, dst)
        if state != "ok" or args.force:
            todo.append((src, dst, lang, state))
    if args.check:
        for src, dst, _, state in todo:
            print(f"⚠ {dst} needs regenerating: {REASON[state]} (source {src}). Run python3 scripts/translate.py")
        if not todo:
            print("✓ all translations match their sources")
        return 0
    for src, dst, lang, state in todo:
        print(f"→ {src} → {dst} ({state})", flush=True)
        translate(src, dst, lang, args.model)
    if not todo:
        print("✓ all translations are up to date")
    return 0


if __name__ == "__main__":
    sys.exit(main())
